// from src/locales/ja/blog.ts. Body + FAQs for article 'how-to-convert-image-to-pdf' (ja).
// This file is the single source for this article's ja body text.
import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "<p>画像をPDFに変換するのは、日常で最も役立つファイル作業の一つです。写真が書類になり、スキャンの一式が1つのファイルになり、送るにも印刷するにも準備が整います。</p>\n<p>作業全体は数分で終わります。長い書類でも同様です。画像をアップロードし、並べ替え、ページサイズを選んで、完成したPDFをダウンロードします。</p>\n<p>この記事では、各ステップを順番に解説します。初めてのPDFも、きれいでプロらしく仕上がります。</p>\n<h2 id=\"gather-your-images\">ステップ0：画像を集めて準備する</h2>\n<p>ツールを開く前に、書類に入れる画像をすべて集めてください。たとえばパスポート申請では、写真、署名、スキャンしたフォームが必要になるかもしれません。</p>\n<p>各画像の向きが正しいか確認します。横向きのスキャンは横向きのページになるので、傾いた画像は先に回転ツールで直してください。</p>\n<p>最も画質のよい原本を使いましょう。ぼやけたスキャンはPDFの中でもシャープになりませんし、低解像度の写真は印刷するとさらに悪く見えます。</p>\n<p>1ファイルあたり20MBまで受け付けます。ほとんどのスマホ写真やスキャンはこの制限を大きく下回るので、事前に小さくする作業はまず不要です。</p>\n<h2 id=\"open-the-tool\">ステップ1：画像をPDFに変換するツールを開く</h2>\n<p><a href=\"/ja/gazou-pdf-henkan/\">画像をPDFに変換するツール</a>をブラウザで開いてください。Windows、Mac、Linux、ChromeOS、Android、iOSで動作し、インストールは不要です。</p>\n<p>アップロードエリアと、その下に書類設定が表示されます。設定は作業中ずっと見えているので、生成前にいつでも調整できます。</p>\n<p>アカウントは不要で、アップロードもありません。PDFは端末内で作られるので、身分証やレシートの画像でも安心です。</p>\n<p>スマホの場合は、モバイルブラウザでページが使えます。アップロードエリアをタップして、ギャラリーから写真を選んでください。</p>\n<h2 id=\"upload-and-order\">ステップ2：画像をアップロードして順番を決める</h2>\n<p>画像をアップロードエリアにドラッグするか、クリックしてファイル選択画面を開きます。Ctrl+Vでスクリーンショットを直接貼り付けることもでき、急ぎの書類に便利です。</p>\n<p>画像は、追加した順番でページ順リストに表示されます。ページを上下にドラッグして、正しい順序になるまで並べ替えてください。</p>\n<p>リストを確認したあとで、画像を追加することもできます。新しい画像は末尾に入り、他のページと同じようにドラッグして配置できます。</p>\n<p>重複したページや不要なページは、今のうちに取り除きましょう。生成前にリストを直すほうが、PDFを作り直すよりずっと簡単です。</p>\n<h2 id=\"choose-page-size\">ステップ3：ページサイズを選ぶ</h2>\n<p>ほとんどの書類にはA4を選んでください。世界のほとんどの地域の標準サイズで、フォーム、申請書、スキャンした書類には公的システムがA4を前提としています。</p>\n<p>送り先がアメリカやカナダの場合、またはフォームがレターサイズを明記している場合は、USレターを選んでください。違いは小さいですが、印刷すると目に見えます。</p>\n<p>写真集の場合は、画像サイズに合わせる設定を選んでください。各ページが画像とぴったり同じサイズになり、余白も切り取りもなく、アルバムやスキャンの保管に合います。</p>\n<p>迷ったらA4が安全な既定値です。ほぼどこでも正しく印刷でき、画面でもプロらしく見えます。</p>\n<h2 id=\"set-orientation\">ステップ4：向きと配置を設定する</h2>\n<p>向きは、理由がない限り自動判別にしておきましょう。自動判別は各画像を読み取り、縦の写真には縦のページ、横の写真には横のページを与えます。</p>\n<p>すべての画像が同じ形なら、縦か横に固定して書類を統一することもできます。ページがそろうと、正式な提出物はすっきり見えます。</p>\n<p>配置は、書類には全体表示を選んでください。全体表示は画像全体をページ内に収めるので、署名や隅が切り取られることはありません。</p>\n<p>全面表示は写真集だけに使ってください。端までいっぱいのページは見栄えがよいですが、はみ出しを切り取るので、身分証やフォームには使わないでください。</p>\n<h2 id=\"margins-and-quality\">ステップ5：余白と画質を設定する</h2>\n<p>目的に合った余白を選んでください。余白なしは全面写真、余白小は一般的な書類、余白中は印刷してファイリングするものに向いています。</p>\n<p>プリンターは紙の端まで印刷できないことを忘れないでください。余白なしのPDFは紙の上で画像の端が少し切れることがあるので、印刷するものは少なくとも小さい余白を使いましょう。</p>\n<p>文字や身分証の写真は、画質スライダーを高く設定してください。小さな文字は低画質ですぐぼやけ、ぼやけた書類は却下されることがあります。</p>\n<p>画面で見る写真アルバムなら、中くらいの画質で十分です。画像はきれいに見え、PDFもメールで送れるサイズに収まります。</p>\n<h2 id=\"preview-and-check\">ステップ6：プレビューしてすべて確認する</h2>\n<p>ページ順リストをもう一度見直してください。順番、各ページの向き、上下逆さまのページがないかを確認します。</p>\n<p>ページサイズと余白が目的に合っているか確認します。A4で余白付きが必要なフォームが、余白なしの画像サイズ合わせで届いてはいけません。</p>\n<p>ファイル名の設定も確認してください。visa-documents.pdfのような分かりやすい名前なら、相手は開かなくても内容が分かります。</p>\n<p>ここが、安く修正できる最後のチャンスです。今1分かけて確認すれば、あとで作り直す手間が省けます。</p>\n<h2 id=\"generate-and-download\">ステップ7：PDFを生成してダウンロードする</h2>\n<p>生成ボタンをクリックしてください。「Encoding page X of Y」という進捗メッセージが表示され、書類がページごとに作られていく様子が分かります。</p>\n<p>生成は、短い書類なら数秒、長い書類でも少し長くかかる程度です。20ページでも、たいてい30秒以内に終わります。</p>\n<p>ダウンロードダイアログが表示されたら、ファイルを保存してください。ダイアログに気付く前に消えてしまった場合は、ダウンロードフォルダを確認してください。ファイルは自動でそこに保存されています。</p>\n<p>完成したPDFを開いて、通して確認してください。ページ数、順番、最も小さい文字が読めるかを確かめます。</p>\n<ol>\n<li>画像をPDFに変換するツールを開いて画像をアップロードする。</li>\n<li>ページを正しい順番に並べる。</li>\n<li>ページサイズ、向き、余白、画質を選ぶ。</li>\n<li>PDFを生成し、送る前に確認する。</li>\n</ol>\n<h2 id=\"converting-a-single-photo\">1枚の写真をPDFにする</h2>\n<p>1枚の写真も同じ手順で1ページのPDFになります。写真をアップロードし、ページサイズを選んで生成するだけです。</p>\n<p>1枚の写真では、画像サイズに合わせる設定が最もよいことが多いです。ページが写真とぴったり同じサイズになり、白い枠も無駄なスペースもありません。</p>\n<p>1枚の写真のPDFは、相手に書類形式が必要なときに便利です。PDFアップロードしか受け付けないフォームもあり、これが最も早い対応方法です。</p>\n<p>ファイル名は分かりやすく付けましょう。profile-photo.pdfのような名前なら、相手はすぐに内容が分かります。</p>\n<h2 id=\"converting-scans\">スキャンした書類を変換する</h2>\n<p>スキャンは、最も多いPDFの用途です。複数ページのフォーム、契約書、レシートの一式が、1つのすっきりした書類になります。</p>\n<p>スキャンにはA4サイズと全体表示を使ってください。この組み合わせなら、すべての文字が見え、すべてのページが同じサイズになります。</p>\n<p>スキャンでは画質スライダーを高く保ってください。小さな文字や署名は低画質ですぐぼやけ、ぼやけたスキャンは受付で却下されることがあります。</p>\n<p>スキャナーを自分で操作できる場合は、200DPI以上でスキャンしてください。低解像度のスキャンは、PDFの画質設定をどうしてもシャープにできません。</p>\n<h2 id=\"fixing-common-problems\">よくあるトラブルと対処法</h2>\n<p>ページが横向きになった場合、元画像が横向きでした。画像を追加する前に回転させるか、取り除いて回転させてから追加し直してください。</p>\n<p>PDFが大きすぎてメールに添付できない場合は、画質スライダーを1段階下げてもう一度生成してください。写真は中画質でもよく圧縮できますが、スキャンはやさしく扱う必要があります。</p>\n<p>ページが切り取られている場合は、全面表示を選んでいた可能性があります。全体表示に切り替えて生成し直せば、画像全体が収まります。</p>\n<p>ダウンロードダイアログが消えた場合は、ダウンロードフォルダを確認してください。ダイアログを閉じてもファイルはそこにあるので、生成し直す必要はありません。</p>\n<h2 id=\"mobile-tips\">スマホとタブレットのコツ</h2>\n<p>スマホでは、アップロードエリアをタップしてギャラリーから写真を選びます。複数枚を一度に選択でき、選んだ順番で読み込まれます。</p>\n<p>順番リストのページは、指でドラッグして並べ替えます。リストはタッチ操作に対応しており、長押しでドラッグが始まるのが一般的です。</p>\n<p>ダウンロードしたファイルは、スマホのダウンロードフォルダに入ります。iPhoneはファイルアプリ、Androidはファイルマネージャーを開いてください。</p>\n<p>長い書類は、できればパソコンを使ってください。大きな画面のほうが、20ページの並べ替えがはるかに楽です。</p>\n<h2 id=\"receipts-for-expenses\">経費精算用のレシートを変換する</h2>\n<p>経費申請にはレシートが必要で、レシートのPDFは写真フォルダよりはるかにすっきりしています。出張や月ごとに1つの書類にまとめれば、経理チームも助かります。</p>\n<p>各レシートは、平らに置いてよい光で影なく撮影してください。傾いたり影が入ったりしたレシートは読みにくく、経理に却下されることがあります。</p>\n<p>A4サイズで全体表示を使い、すべてのレシートがページに完全に収まるようにしてください。合計金額の切り取りや日付の欠落は、申請却下の最も多い理由です。</p>\n<p>レシートは画質スライダーを高く保ってください。税番号や明細の行といった小さな文字は、低画質ですぐぼやけます。申請にはこれらの詳細が必要です。</p>\n<p>PDFの名前は、月と目的で付けましょう。expenses-november-2026.pdfのような名前なら、経理チームが正しく整理し、あとで見つけやすくなります。</p>\n<h2 id=\"portfolio-pdf\">ポートフォリオPDFを作る</h2>\n<p>ポートフォリオPDFは、自分の最良の作品を1つの書類で見せる方法です。デザイナー、フォトグラファー、フリーランスは、クライアントを獲得するために使います。</p>\n<p>まず最も強い画像を選び、意図した順番に並べてください。最初のページが最良の作品であるべきです。最初の印象が、そのあとのすべてを決めます。</p>\n<p>ポートフォリオには、画像サイズに合わせる設定を使いましょう。各画像が白い枠なしでページいっぱいに広がり、印刷した本のように意図的でプロらしく見えます。</p>\n<p>ファイルサイズはほどほどに保ってください。メールで送れないほど大きなポートフォリオは役に立ちません。画質とサイズのバランスを取り、できれば10MB以内を目指しましょう。</p>\n<p>最後のページに連絡先を入れてください。作品を気に入ったクライアントは、メールアドレスや電話番号をすぐに見つけられるべきです。</p>\n<h2 id=\"photos-and-scans-together\">写真とスキャンを1つのPDFにまとめる</h2>\n<p>実際の書類は、写真とスキャンが混ざることがよくあります。ビザ申請には、JPGの写真、パスポートのPNGスキャン、銀行明細のJPGスキャンが含まれるかもしれません。</p>\n<p>PDF作成ツールは、混ざった形式を1つの書類で受け付けます。各ページは元の形式のままなので、すべてを1つの形式に変換しておく必要はありません。</p>\n<p>ページは論理的な順番に並べ、身分証を最初に、裏付け資料をあとにしてください。分かりやすい順番は、読み手が申請の流れを追う助けになります。</p>\n<p>生成後は、混ざったページを注意深く確認してください。写真のページとスキャンのページでは、求める画質設定が異なる場合があり、1つのスライダーでは妥協が必要になります。</p>\n<p>1つのページだけおかしい場合は、PDF設定ではなく元画像を調整してください。問題のある写真を先に正しい形式へ変換し、そのあとPDFを作り直します。</p>\n<h2 id=\"sending-the-pdf\">PDFを相手に送る</h2>\n<p>送る前に、完成したPDFを受け取る人の目で開いて読んでください。ページ数、順番、最も小さい文字が読めるかを確認します。</p>\n<p>メールで送る場合は、サイズ制限以内ならPDFを直接添付してください。ほとんどのサービスは20MBから25MBまで対応しており、よく作られたPDFはたいていそれよりずっと小さいです。</p>\n<p>大きなPDFは、クラウドストレージにアップロードしてリンクを共有してください。相手はサイズの問題なくファイルをダウンロードでき、あとでリンクを取り消すこともできます。</p>\n<p>メッセージアプリで送る場合は、PDFが画像ではなく書類として送られるか確認してください。WhatsAppもTelegramもPDF添付に対応しており、レイアウトが保たれます。</p>\n<p>送ったあとは、送信フォルダにコピーを残してください。相手が紛失したり、別の版を求めたりした場合、最初からやり直さずに再送や作り直しができます。</p>\n<h2 id=\"id-photos-applications\">申請用の身分証写真を変換する</h2>\n<p>申請フォームでは、身分証写真をPDFの1ページとして求められることが多く、写真は鮮明でなければなりません。ぼやけた身分証写真は、申請を数週間遅らせることがあるので、変換には注意が必要です。</p>\n<p>最近撮った、明るくて背景が無地の写真を使ってください。顔は正面を向き、影やサングラスがなく、申請の写真ルールに従っている必要があります。</p>\n<p>A4サイズで全体表示を選び、写真全体がページに収まるようにしてください。あごや額の切り取りは、身分証写真が却下される最も多い理由です。</p>\n<p>身分証の写真は、画質スライダーを高く保ってください。目や口といった小さな細部は鮮明に残す必要があり、申請システムがそれらをチェックします。</p>\n<p>生成後はファイルサイズを確認してください。アップロード上限が2MBのポータルでは、大きなPDFが却下されることがあります。画質を1段階下げる必要があるかもしれません。</p>\n<p>ばらばらの画像から、1つのきれいなPDFにする流れは以上です。</p>\n<p>詳しい解説は<a href=\"/ja/blog/gazou-pdf-henkan-gaido/\">画像をPDFに変換する完全ガイド</a>、形式の選択は<a href=\"/ja/blog/jpg-pdf-vs-png-pdf/\">JPGをPDFに変換 vs PNGをPDFに変換</a>をご覧ください。</p>\n<p>iPhoneのHEICファイルが元画像の場合は、<a href=\"/ja/heic-jpg-henkan/\">HEICからJPGへの変換ツール</a>で先に準備できます。</p>";

export const FAQS: BlogArticleFaq[] = [{"question":"1枚の画像だけでもPDFに変換できますか？複数枚が必要ですか？","answer":"1枚の画像でも問題なく、1ページのPDFになります。ツールはバッチ用に作られていますが、最小枚数はありません。1枚の写真では、画像サイズに合わせる設定が最もきれいな結果になることが多いです。ページが写真とぴったり同じサイズになるからです。"},{"question":"間違った順番で画像をアップロードした場合はどうなりますか？","answer":"生成前に順番を修正できます。ページ順リストで、ページを上下にドラッグすれば、順序が正しくなります。その段階で画像の追加や削除もできます。順番が正しくなったら、PDFを生成してください。"},{"question":"スマホから画像をPDFに変換できますか？","answer":"はい、できます。スマホのブラウザでツールを開き、アップロードエリアをタップしてギャラリーから写真を選んでください。すべての設定がタッチ操作に対応し、完成したPDFはスマホにダウンロードされます。長い書類はパソコンのほうが楽ですが、短い書類ならスマホで十分です。"},{"question":"PDFは元の画像の画質を保てますか？","answer":"おおむね保てますが、画質スライダーが重要です。高画質なら、PDF内の画像は元の画像とほぼ同じです。低画質では圧縮されて柔らかく見えることがあります。文字のある書類は、画質を高く保ってください。"},{"question":"作成したPDFにパスワードを設定できますか？","answer":"このツールではできません。暗号化なしの標準的なPDFを作るツールだからです。パスワードが必要な場合は、完成したPDFをパスワード保護に対応したPDFアプリで開き、そこで設定してください。生成されるファイル自体は、通常の保護なしPDFです。"},{"question":"画像をPDFに変換するとファイルサイズは小さくなりますか？","answer":"画質スライダーによっては、小さくなる場合があります。中画質では、PDF内の画像が圧縮されるので、合計ファイルは元の画像の合計より小さくなることが多いです。高画質では、PDFの構造そのものの分だけ、同じくらいのサイズか少し大きくなる場合があります。"}];
